#!/usr/bin/env bash
set -Eeuo pipefail
B="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; cd "$B"; port=${TF_FRONTEND_PORT:-$([[ ${OPERACIONES_GLOBAL:-0} == 1 ]] && echo 18111 || echo 8111)}; vars=(-var="frontend_port=$port" -var="postgres_password=devops123")
case ${1:-} in iniciar) docker build --provenance=false -t operaciones1-guia11-backend:local backend; docker build --provenance=false -t operaciones1-guia11-frontend:local frontend; terraform init -input=false; terraform apply -auto-approve -input=false "${vars[@]}";; detener) echo 'Se destruirán únicamente recursos TP11 gestionados por este state.'; terraform destroy -auto-approve -input=false "${vars[@]}";; reiniciar) "$B/operaciones.sh" detener; "$B/operaciones.sh" iniciar;; estado) terraform output; docker ps --filter label=managed-by=terraform;; verificar) terraform fmt -check -recursive; terraform init -input=false; terraform validate; terraform plan -input=false -out=runtime.plan "${vars[@]}"; terraform apply -auto-approve -input=false runtime.plan; terraform output; for _ in $(seq 1 60); do curl -fsS "http://127.0.0.1:$port/health" | jq -e '.status=="ok"' >/dev/null && exit 0; sleep 1; done; exit 1;; logs) docker logs "operaciones1-guia11-dev-backend" --tail=100 2>/dev/null || terraform show;; *) exit 64;; esac
